_AUTHOR_SOURCE='#!/usr/bin/env python3\n"""Independent literal/list ledger. Does not read/import the production model or outputs.\nCNY million. Inputs transcribed from the public-source/budget specifications; calculations\nuse positional accounts and separate balance postings. External comparison is separate.\n"""\nimport json, copy, math\n# cash, plant, working, investments, debt, internal loan, mother cost, nominal capital,\n# legal reserve, protected capital, earnings, dividend asset, dividend liability,\n# ownership, active, internal loan asset.\nC,A,W,F,B,L,I,R,S,K,E,V,D,O,T,J=range(16)\nNAMES=[\'serbia\',\'foshan\',\'jilin\',\'electronics\',\'hongkong\',\'japan\',\'europe\',\'shanghai\',\'trade\',\'digital\',\'chongqing\',\'robot\',\'parent\']\n# All literal; no external input parsing.\nSTART=[\n [.8,856.62629929,100,560,0,30,856.62629929,1],\n [195,195,55,113.2846,0,0,195,1],\n [185,185,20,185,0,0,185,1],\n [150,35.5,20,15.5,0,0,35.5,1],\n [56,475.761158,50,27.8021,290,0,425.98189657,1],\n [5.79924828,5.79924828,1,1.495,0,0,5.79924828,1],\n [.81359421,.81359421,.2,.0029,0,0,.81359421,1],\n [20,20,8,12.5938,0,0,20,1],\n [1,1,20,23.57,0,0,1,1],\n [5,1,1,.6113,0,0,1,1],\n [100,25,8,17,0,0,25,1],\n [100,10,7,2.950068,0,0,7,.7]]\nPARAMETERS={\'base\':[.095,.015,1,0,1,.15],\'core_low\':[.10,.01,.98,-.004,1.1,.17],\'core_high\':[.09,.02,1.02,.003,.95,.145],\'margin_minus_1pct\':[.095,.015,1,-.01,1,.15]}\nREVENUE=[14500,15400,16600,17900,19000,20000,20900,21700,22400,23000]\nGROSS=[.185,.188,.193,.196,.198,.198,.197,.196,.195,.195]\nRD=[.069,.068,.065,.063,.062,.061,.061,.061,.061,.061]\nSERREV=[620,780,1050,1350,1600,1780,1930,2050,2150,2250]\nSERNI=[-.035,-.01,.015,.035,.05,.055,.055,.055,.055,.055]\nELECREV=[100,300,650,1050,1500,1800,2000,2200,2300,2400]\nHKREV=[0,40,120,200,260,300,340,370,390,400]\nCQREV=[100,250,400,550,650,700,750,800,830,850]\nNEWNI=[-.04,-.01,.02,.05,.065,.07,.07,.07,.07,.07]\nPREBUILD={0:[250,450,500,450,350,250,150,80,40,0],3:[350,650,800,800,700,600,400,200,100,0],4:[100,180,220,220,180,120,70,30,0,0],10:[40,80,100,100,80,60,40,20,0,0]}\nSUPPORT={2,5,6,7,8,9}\nFOREIGN={0,4,5,6}\n\ndef first_ledger():\n q=[]\n for idx,(reg,paid,cash,capital,financial,debts,cost,share) in enumerate(START):\n  ln=20.37896907 if idx==2 else 0\n  q.append([cash,.7*capital,.3*capital,financial,debts,ln,cost,reg,0,paid,cash+capital+financial-debts-ln-paid,0,0,share,1,0])\n groupcash=3092.17215210+466.82670520-56.64173080-10.4155\n groupequity=11479.98602406+2.98502040-10.4155\n groupworking=groupequity-groupcash-790.32425928+148.44249566\n pcash=groupcash-sum(v[C] for v in q)\n pworking=groupworking-sum(v[A]+v[W] for v in q)\n pfin=790.32425928-sum(v[F] for v in q)\n pdebt=148.44249566-sum(v[B] for v in q)\n pprotect=285.679419+4129.40171388-294.97339946+35.71545467-10.4155\n costs=sum(v[I] for v in q);loan=sum(v[L] for v in q)\n pre=pcash+pworking+pfin+costs+loan-pdebt-pprotect-179.34606582\n q.append([pcash,.7*pworking,.3*pworking,pfin,pdebt,0,costs,285.679419,179.34606582,pprotect,pre,0,0,1,1,loan])\n h=q[4];blocked=max(0,h[E]);h[K]+=blocked;h[E]-=blocked\n return q,285.528419\n\ndef nth(a,t):return a[min(len(a)-1,t-1)]\n\ndef book_profit(q,idx,amount):\n a=q[idx];net_after=a[E]+amount\n eligible=min(max(amount,0),max(net_after,0))\n appropriation=0 if idx in FOREIGN else min(.10*eligible,max(.5*a[R]-a[S],0))\n a[S]+=appropriation;a[E]=net_after-appropriation\n return appropriation\n\ndef legal_id(q):\n for i,a in enumerate(q):\n  lhs=a[C]+a[A]+a[W]+a[F]+a[V]-a[B]-a[L]-a[D]\n  if i==12:lhs+=a[I]+a[J]\n  rhs=a[K]+a[S]+a[E]\n  assert math.isclose(lhs,rhs,rel_tol=1e-8,abs_tol=1e-7),(i,\'independent legal identity\',lhs,rhs)\n  assert a[C]>=-1e-7 and a[D]<=a[C]+1e-7\n assert math.isclose(q[12][J],sum(v[L] for v in q[:12]),abs_tol=1e-7)\n assert math.isclose(q[12][V],sum(v[D]*v[O] for v in q[:12]),rel_tol=1e-8,abs_tol=1e-7)\n return sum(v[C]+v[A]+v[W]+v[F]-v[B] for v in q)-sum(v[D]*(1-v[O]) for v in q[:12])\n\ndef forecasts(y,p):\n rate,growth,scale,adjust,multiple,working=p\n factor=(1+growth)**max(0,y-10)\n total=nth(REVENUE,y)*scale*factor\n rev=[nth(SERREV,y)*scale*factor,total*.045,total/14500*30,nth(ELECREV,y)*scale*factor,nth(HKREV,y)*factor,0,0,0,0,0,nth(CQREV,y)*factor,(20*total/14500 if y>=4 else 0)]\n rev.append(total-sum(rev));plans=[]\n for i,r in enumerate(rev):\n  if i==12:margin=(nth(GROSS,y)+adjust-nth(RD,y)-.030+.006)*.85\n  elif i==0:margin=nth(SERNI,y)+.7*adjust\n  elif i in (3,4,10):margin=nth(NEWNI,y)+adjust\n  elif i==11:margin=-.2\n  else:margin=.04+.5*adjust\n  ni=r*margin\n  if i in (5,6,7,9):ni=0\n  if i==11:ni-=nth([10,12,15,15,10],y)*total/14500\n  wc=working if i==12 else .16\n  if i==12 and y>10 and wc>.17:wc-=min(wc-.17,(y-10)*.01)\n  plant=(r*(.24 if i==12 else .32)+nth(PREBUILD.get(i,[0]),y))*multiple\n  plans.append([r,ni,plant,r*wc,r*.06])\n return plans\n\ndef project(p,years=960,checkpoint=None):\n if checkpoint is None:q,shares=first_ledger();first=1\n else:q,shares=copy.deepcopy(checkpoint);first=6\n initial=copy.deepcopy([q,shares]);rows=[];pv=0;fifth=None\n for year in range(first,years+1):\n  old_total=sum(v[C] for v in q);old_equity=legal_id(q)\n  old_minor=sum(v[D]*(1-v[O]) for v in q[:12])\n  parent=q[12];plan=forecasts(year,p)\n  account_flows=[0.0]*10 # net income, dep, capex, dWC, sale proceeds, sale loss, principal, minority capital, minority pay, buyback\n  received=sum(v[D]*v[O] for v in q[:12]);minor_paid=old_minor\n  parent[C]+=received;parent[V]-=received\n  for v in q[:12]:v[C]-=v[D];v[D]=0\n  account_flows[8]+=minor_paid\n  if year==1:\n   account_flows[9]=89.5845;parent[C]-=89.5845;parent[K]-=89.5845\n   cancelled=89.5845/148.31;shares-=cancelled;parent[R]-=cancelled+.151\n  operations=[]\n  # Each posting is entered from the independent beginning-year account vector.\n  for idx,a in enumerate(q):\n   if not a[T]:operations.append(None);continue\n   sales,opni,targetplant,targetwc,floor=plan[idx]\n   oldplant=a[A];oldwc=a[W];olddebt=a[B]\n   income=.015*a[F]+.01*max(a[C]-a[D]-floor,0)\n   if idx in (5,6,7,8,9):income=0\n   expense=.045*olddebt\n   depreciation=min(oldplant,max(.1*oldplant,.028*sales))\n   newplant=max(oldplant-.35*depreciation,targetplant)\n   if idx in SUPPORT:newplant=oldplant;targetwc=oldwc\n   investment=newplant-oldplant+depreciation\n   change_wc=targetwc-oldwc\n   sale=a[F]*(.1 if year<=10 else .2)\n   loss=.1*sale;profit=opni+income-expense-loss\n   # Cash from earnings before noncash financial loss, not a second profit credit.\n   a[C]+=opni+income-expense+depreciation-investment-change_wc+.9*sale\n   a[A]=newplant;a[W]=targetwc;a[F]-=sale\n   payment=min(olddebt,olddebt/max(1,6-year)) if year<=5 else olddebt*.2\n   payment=min(payment,max(0,a[C]-floor));a[C]-=payment;a[B]-=payment\n   reserve=book_profit(q,idx,profit)\n   posting=[profit,depreciation,investment,change_wc,.9*sale,loss,payment]\n   for j,v in enumerate(posting):account_flows[j]+=v\n   operations.append([sales,profit,depreciation,investment,change_wc,reserve])\n  # Equity subscription and old intercompany principal settlement are distinct.\n  for idx in range(12):\n   a=q[idx]\n   if not a[T]:continue\n   required=max(plan[idx][4]-a[C],0)\n   a[C]+=required;a[K]+=required\n   parent[C]-=required*a[O];parent[I]+=required*a[O];a[I]+=required*a[O]\n   account_flows[7]+=required*(1-a[O])\n   loanpayment=min(a[L],max(0,a[C]-plan[idx][4])*.2)\n   a[C]-=loanpayment;a[L]-=loanpayment;parent[C]+=loanpayment;parent[J]-=loanpayment\n  exitcash=0;exitloss=0\n  if year==4:\n   a=q[11];pre_cash=sum(v[C] for v in q);pre_equity=legal_id(q)\n   # Robot termination: explicit waterfall, historical plus subsequent cost retained.\n   realize=.55*a[A]+.80*a[W]+.80*a[F]\n   impairment=a[A]+a[W]+a[F]-realize+2\n   a[C]+=realize-2;book_profit(q,11,-impairment)\n   a[A]=a[W]=a[F]=0\n   assert a[C]>=a[B];a[C]-=a[B];a[B]=0\n   recovery_loan=min(a[C],a[L]);parent[C]+=recovery_loan;parent[J]-=a[L]\n   a[C]-=recovery_loan;book_profit(q,12,-(a[L]-recovery_loan));a[L]=0\n   residual=a[C];returned=residual*a[O];minor=residual*(1-a[O]);book_profit(q,12,returned-a[I])\n   parent[C]+=returned;parent[I]-=a[I]\n   for key in (C,I,K,S,E):a[key]=0\n   a[T]=0\n   account_flows[8]+=minor\n   exitcash=sum(v[C] for v in q)-pre_cash+minor\n   exitloss=pre_equity-legal_id(q)-minor\n  newdebt=max(0,plan[12][4]-parent[C]);assert parent[B]+newdebt<2000\n  parent[B]+=newdebt;parent[C]+=newdebt\n  declared=0;tax=0\n  for idx,a in enumerate(q[:12]):\n   if not a[T]:continue\n   available=.8*max(0,a[C]-a[D]-plan[idx][4]);d=min(max(0,a[E]),available)\n   a[E]-=d;a[D]+=d;parent[V]+=d*a[O];declared+=d*a[O]\n   if idx in FOREIGN:tax+=.05*d*a[O]\n  parent[C]-=tax;account_flows[0]-=tax;book_profit(q,12,declared-tax)\n  normal=max(0,operations[12][1]+declared)*nth([.38,.4,.42,.45,.48,.55,.62,.70,.78,.85],year)\n  available=max(0,parent[C]-plan[12][4]);add=max(0,available-normal)*(.06 if year<=5 else .15)\n  distribution=min(max(0,parent[E]),available,normal+add)\n  parent[C]-=distribution;parent[E]-=distribution\n  per_share=distribution/shares;pv+=per_share/(1+p[0])**(year-first+1)\n  ni,dep,cap,dwc,proceeds,loss,principals,nci_in,nci_out,repurchase=account_flows\n  expect_cash=old_total+ni+dep-cap-dwc+proceeds+loss-principals+nci_in-nci_out-repurchase+newdebt-distribution+exitcash\n  assert math.isclose(sum(a[C] for a in q),expect_cash,abs_tol=1e-6,rel_tol=1e-8)\n  current_eq=legal_id(q);new_minor=sum(v[D]*(1-v[O]) for v in q[:12])\n  expect_eq=old_equity+ni+nci_in-repurchase-distribution-nci_out-exitloss+old_minor-new_minor\n  assert math.isclose(current_eq,expect_eq,rel_tol=1e-8,abs_tol=1e-6)\n  rows.append({\'year\':year,\'cash\':sum(a[C] for a in q),\'equity\':current_eq,\'shares\':shares,\'dps\':per_share,\'declared\':declared,\'received\':received,\'annual_operating_ledger\':operations,\'closing_accounts\':copy.deepcopy(q)})\n  if year==5:fifth=copy.deepcopy([q,shares])\n return {\'pv\':pv,\'rows\':rows,\'state5\':fifth,\'opening\':initial}\n\ndef main():\n results={name:project(p) for name,p in PARAMETERS.items()}\n s5=results[\'base\'][\'state5\'];term={}\n for name,p in [(\'low\',[.10,.01,1,-.004,1,.15]),(\'high\',[.09,.02,1,.003,1,.15])]:term[name]=project(p,checkpoint=s5)\n print(json.dumps({\'method\':\'independent_literal_positional_annual_ledger\',\'account_order\':[\'cash\',\'ppe\',\'nwc\',\'fin\',\'debt\',\'loan\',\'investment\',\'reg\',\'reserve\',\'paid\',\'re\',\'receivable\',\'payable\',\'own\',\'active\',\'loanrec\'],\'entity_order\':NAMES,\'parameters\':PARAMETERS,\'scenarios\':results,\'continuations\':term},ensure_ascii=False,sort_keys=True,separators=(\',\',\':\'),allow_nan=False))\nif __name__==\'__main__\':main()\n'
with contextlib.redirect_stdout(_buffer):
    exec(compile(_AUTHOR_SOURCE,__file__,"exec"),{"__file__":__file__,"__name__":"__main__"})
