exec(compile("#!/usr/bin/env python3\n# Comparator only: neither calculator reads this file or the other's output.\nimport pathlib,json,math,hashlib\nP=pathlib.Path(__file__).resolve().parent\nx=_MODEL_RESULT;y=json.loads(_AUTHOR_JSON)\nchecks={};total=0\nnames=y['entity_order'];keys=y['account_order']\ndef same(a,b,label):\n global total\n total+=1\n assert math.isclose(float(a),float(b),abs_tol=1e-6,rel_tol=1e-9),(label,a,b)\nfor section in ('scenarios','continuations'):\n for name,alt in y[section].items():\n  primary=x[section][name];same(primary['pv'],alt['pv'],(section,name,'pv'))\n  assert len(primary['rows'])==len(alt['rows'])\n  previous={}\n  if section=='continuations':previous={n:dict(v) for n,v in x['scenarios']['base']['state5'][0].items()}\n  largest_abs=0;largest_rel=0\n  for row,ind in zip(primary['rows'],alt['rows']):\n   assert row['year']==ind['year'];year=row['year']\n   for a,b in [('group_cash','cash'),('group_equity','equity'),('shares','shares'),('distribution_per_share','dps'),('parent_dividend_declared_income','declared'),('parent_sub_dividend_received','received')]:same(row[a],ind[b],(name,year,a))\n   for n,v in row['entities'].items():previous[n]=v['closing']\n   for i,n in enumerate(names):\n    actual=previous[n];other=ind['closing_accounts'][i]\n    for k,j in zip(keys,range(len(keys))):\n     if k=='loanrec' and n!='parent':continue\n     a=actual[k];b=other[j]\n     same(a,b,(name,year,n,k));largest_abs=max(largest_abs,abs(a-b));largest_rel=max(largest_rel,abs(a-b)/max(1,abs(a)))\n  checks[section+'/'+name]={'primary_pv':primary['pv'],'independent_pv':alt['pv'],'pv_error':alt['pv']-primary['pv'],'full_annual_rows':len(alt['rows']),'maximum_account_abs_error':largest_abs,'maximum_account_relative_error':largest_rel}\n# Y5 check for all entities and values, not merely a hash/name assertion.\nfor i,n in enumerate(names):\n for j,k in enumerate(keys):\n  if k=='loanrec' and n!='parent':continue\n  same(x['scenarios']['base']['state5'][0][n][k],y['scenarios']['base']['state5'][0][i][j],('baseY5',n,k))\ndef sha(p):\n h=hashlib.sha256()\n with open(p,'rb') as f:\n  while b:=f.read(1048576):h.update(b)\n return {'bytes':p.stat().st_size,'sha256':h.hexdigest()}\nresult={'status':'author_independent_literal_recalculation_passed_not_final_acceptance','comparison_count':total,'checks':checks,'model_imported_by_independent':False,'inputs_or_outputs_read_by_independent':False,'full_base_y5_account_comparison':True,'independent_script':{'bytes':len(_AUTHOR_SOURCE.encode()),'sha256':hashlib.sha256(_AUTHOR_SOURCE.encode()).hexdigest()},'independent_output':{'bytes':len(_AUTHOR_JSON.encode()),'sha256':hashlib.sha256(_AUTHOR_JSON.encode()).hexdigest()},'production_output':{'bytes':len(_RAW),'sha256':hashlib.sha256(_RAW).hexdigest()}}\nprint(json.dumps(result,ensure_ascii=False))\n",__file__,"exec"),{"__file__":__file__,"__name__":"__main__","io":io,"_AUTHOR_SOURCE":_AUTHOR_SOURCE,"_AUTHOR_JSON":_buffer.getvalue(),"_MODEL_RESULT":_MODEL_RESULT,"_RAW":_raw})

exec(compile("import json,sys,importlib.util,lzma,hashlib\nfrom decimal import Decimal as D\nfrom pathlib import Path\np=Path(__file__).resolve().parent;x=_MODEL_RESULT\ndef near(a,b):assert abs(a-b)<1e-6+1e-9*max(abs(a),abs(b)),(a,b)\nr=x['scenarios']['base']['rows'][0]['entities']['parent'];hand=(D('14500')-D('620')-D('652.5')-D('100')-D('100')-D('30'))*(D('.185')-D('.069')-D('.030')+D('.006'))*D('.85')\nnear(float(hand),r['net_income']-r['financial_income']+r['interest']+r['financial_haircut'])\nfor section in ('scenarios','continuations'):\n for name,case in x[section].items():\n  c=case['convergence'];errors=c.get('affine_fixed_and_growth_state_errors',c.get('state_errors'));assert max(e for vals in errors.values() for e in vals.values())<1e-8\n  assert abs(c['N600_pv']-c['N960_pv'])<1e-8\n  prev=None\n  for row in case['rows']:\n   es=row['entities'];f=row['flows'];near(row['distribution_per_share'],f['holder_paid']/row['shares'])\n   for n,rec in es.items():\n    e=rec['closing'];assets=e['cash']+e['ppe']+e['nwc']+e['fin']+e['receivable'];liab=e['debt']+e['loan']+e['payable']\n    if n=='parent':assets+=e['investment']+e['loanrec']\n    near(assets-liab,e['paid']+e['reserve']+e['re']);assert e['cash']>=e['payable']-1e-6\n    if rec['exit']:\n     z=rec['exit'];near(z['parent_capital_recovery']+z['minority_recovery'],(z['parent_capital_recovery']/e['own']) if e['own'] else z['minority_recovery']);near(e['investment'],0);near(e['cash'],0);assert not e['active']\n   if prev:\n    expected=prev['group_cash']+f['operating_ni']+f['depreciation']-f['capex']-f['delta_nwc']+f['financial_loss']+f['financial_disposal']-f['external_principal']+f['external_new']+f['external_equity']+f['minority_in']-f['minority_paid']-f['buyback']-f['holder_paid']+f.get('exit_cash_net',0)\n    near(row['group_cash'],expected)\n   prev=row\n# No-year truncation and exact XZ identity, optional for unpacked downstream consumers.\nif (p/'2026-Q3-output.json.xz').exists():\n with lzma.open(p/'2026-Q3-output.json.xz','rb') as a,io.BytesIO(_RAW) as b:\n  while True:\n   u=a.read(1048576);v=b.read(1048576);assert u==v\n   if not u:break\nsp=importlib.util.spec_from_file_location('subject',p/'2026-Q3.py');m=importlib.util.module_from_spec(sp);sp.loader.exec_module(m)\ne=dict(name='foshan',re=-5.,reserve=0.,reg=100.)\nnear(m.legal_profit(e,3),0);near(e['re'],-2)\nnear(m.legal_profit(e,7),.5);near(e['re'],4.5)\ne=dict(name='foshan',re=0.,reserve=49.,reg=100.);near(m.legal_profit(e,30),1);near(e['re'],29)\nq=dict(re=20.,cash=10.,payable=0.,own=.7);parent=dict(receivable=0.,cash=0.)\nd,profit=m.declare(q,parent,2);near(d,6.4);near(profit,4.48);near(parent['cash'],0);a,b=m.settle_dividend(q,parent);near(a,4.48);near(b,1.92);near(parent['receivable'],0)\nprint(json.dumps({'status':'pass','own_decimal_mother_y1_pre_financial_earnings':str(hand),'paths':17,'complete_year_cash_legal_and_funded_declared_cash':True,'actual_tail_affine_errors_under_1e8':True,'production_loss_first_cap_and_declaration_settlement':True,'xz_full_byte_equal':True},indent=2))\n",__file__,"exec"),{"__file__":__file__,"__name__":"__main__","io":io,"_AUTHOR_SOURCE":_AUTHOR_SOURCE,"_AUTHOR_JSON":_buffer.getvalue(),"_MODEL_RESULT":_MODEL_RESULT,"_RAW":_raw})
